-- Migración 0005: alineación de estructura con "Matriz Oficial" (23/11/2026).
-- IMPORTANTE: antes de ejecutar, hacer backup desde Supabase.
-- Mantiene identificadores p1..p12 y subprocesos históricos; NO elimina nada.
-- No toca indicadores, metas, registros, evidencias, usuarios, archivos ni roles.
-- Requiere el esquema 0000 y los IDs institucionales previos; no reejecutar
-- los seeds 0001-0004 sin revisar (podrían revertir nombres o mediciones).
BEGIN;
ALTER TABLE public.subprocesos ADD COLUMN IF NOT EXISTS codigo text;
ALTER TABLE public.subprocesos ADD COLUMN IF NOT EXISTS responsable text;
ALTER TABLE public.procedimientos ADD COLUMN IF NOT EXISTS codigo text;
ON CONFLICT(id) DO UPDATE SET nombre=excluded.nombre,pilar=excluded.pilar,descripcion=excluded.descripcion;
ON CONFLICT(id) DO UPDATE SET codigo=excluded.codigo,nombre=excluded.nombre,criterio_id=excluded.criterio_id,area=excluded.area,lider=excluded.lider;

ON CONFLICT(id) DO UPDATE SET proceso_id=excluded.proceso_id,nombre=excluded.nombre,codigo=excluded.codigo,responsable=excluded.responsable;

ON CONFLICT(id) DO NOTHING;

ON CONFLICT(id) DO NOTHING;

ON CONFLICT(id) DO NOTHING;

COMMIT;
